1	export type Item = { type: string };
2	export type Step = { items: Item[] };
3	export type Scenario = { steps: Step[] };
4	export type Result = { premium: number };
5	export type ScenarioOutcome = { results: Result[] };
6	
7	const BASE_PREMIUMS: Record<string, number> = {
8	  sword: 100,
9	  amulet: 60,
10	  staff: 80,
11	  potion: 40,
12	  rune: 25,
13	  moonstone: 25,
14	};
15	
16	const FIRST_INSURANCE_SURCHARGE = 1.1;
17	const PROCESSING_FEE = 5;
18	
19	// Guards against binary-float artifacts (e.g. 52.800000000000004) tipping an
20	// exact value over a whole-gold boundary and inflating the premium by 1 G.
21	const FLOAT_ARTIFACT_PRECISION = 6;
22	
23	const roundUpToWholeGold = (amount: number): number =>
24	  Math.ceil(Number(amount.toFixed(FLOAT_ARTIFACT_PRECISION)));
25	
26	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
27	
28	const BUILDING_BLOCK_SIZE = 3;
29	const BUILDING_BLOCK_PREMIUM = 60;
30	
31	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
32	  const items = scenario.steps[0].items;
33	  const isBuildingBlock =
34	    items.length === BUILDING_BLOCK_SIZE &&
35	    items.every((item) => item.type === items[0].type);
36	  const totalBasePremium = isBuildingBlock
37	    ? BUILDING_BLOCK_PREMIUM
38	    : items.reduce((total, item) => total + basePremiumOf(item), 0);
39	  const premium =
40	    roundUpToWholeGold(totalBasePremium * FIRST_INSURANCE_SURCHARGE) +
41	    PROCESSING_FEE;
42	  return { results: [{ premium }] };
43	};
